<?php require_once __DIR__.'/_common.php';$years=ns_years($pdo);$year=ns_year($years);$leaders=[];$events=[];if($year){$s=$pdo->prepare('SELECT frc_team_number,rating,auto_rating,teleop_rating,endgame_rating FROM augur_epa_season_ratings WHERE season_year=? ORDER BY rating DESC LIMIT 12');$s->execute([$year]);$leaders=$s->fetchAll(PDO::FETCH_ASSOC);$s=$pdo->prepare('SELECT tba_event_key,name,start_date FROM augur_epa_archive_events WHERE season_year=? ORDER BY start_date DESC LIMIT 8');$s->execute([$year]);$events=$s->fetchAll(PDO::FETCH_ASSOC);}ns_head('Explore FRC performance');?>
